-- Phase 4 tuning table (square_roundabouts_tuning.lua, generated by tools/gen_roundabouts_tuning.py
-- from the probe search): the shipped table holds engine data, and each part (exact engine
-- radius, splitter rule + floor, Magic size floor) does what it says when a table is injected
-- (geom.setTuning). PLAN.md "Phase 4b notes".

local DIR = "square_roundabouts::/infrastructure/street_construction/"
local geom = ug_require(DIR .. "square_roundabouts_geometry.lua")
local magic = ug_require(DIR .. "square_roundabouts_magic.lua")
local K = geom.PARAM_KEYS
local D = geom.DEV_KEYS

local here = debug.getinfo(1, "S").source:match("^@(.*/)") or "tests/square_roundabouts/"
local G = loadfile(here .. "golden.lua", "t", _ENV)()

local function spec(over, dev)
	local p = {}
	for k, v in pairs(over or {}) do p[K[k]] = v end
	for k, v in pairs(dev or {}) do p[D[k]] = v end
	return geom.readParams(p)
end
local function build(over, dev) return geom.build(spec(over, dev)) end
local function roleLists(b, role)
	local out = {}
	for _, l in ipairs(b.lists) do if l.role == role then out[#out + 1] = l end end
	return out
end
local function text(v) return table.concat(G.serialize(v)) end

--- Runs fn with an injected tuning table, always restoring the generated one.
local function with(t, fn)
	geom.setTuning(t)
	local okRun, err = pcall(fn)
	geom.setTuning(nil)
	if not okRun then error(err, 0) end
end
local EMPTY = { radius = {}, magic = {}, splitter = {} }

test("the shipped tuning table holds engine data (version 2)", function()
	local t = geom.tuning
	eq(t.version, 2)
	ok(next(t.radius) ~= nil, "radius part")
	for pattern, cells in pairs(t.radius) do
		local any = false
		for r0, v in pairs(cells) do
			ok(r0 == 8 or r0 == 20 or r0 == 40 or r0 == 60, pattern .. ": probed slider radius " .. r0)
			ok(v == 0 or v >= r0, pattern .. ": exact radius below its slider radius")
			if v > 0 then any = true end
		end
		ok(any, pattern .. ": a pattern with only 0 cells is left out")
	end
	-- Magic: town and country large from Large (probe search_magic_sizes, 2026-10-08 sizes)
	eq(magic.sizeFloor(magic.readParams({ sqrb_magic_size = 1, sqrb_arm_type = 3 })), 4)
	eq(magic.sizeFloor(magic.readParams({ sqrb_magic_size = 3, sqrb_arm_type = 6, sqrb_direction = 2 })), 4)
	eq(magic.sizeFloor(magic.readParams({ sqrb_magic_size = 1, sqrb_arm_type = 2 })), nil)
	-- splitter rules for medium and large arms on every ring, floors for every layout with arms
	for _, arm in ipairs({ 2, 3, 5, 6 }) do
		for lanes = 1, 3 do
			local rule = geom.splitterRule(spec({ splitter = 2, armType = arm, lanes = lanes }))
			ok(rule and rule.floor, "rule " .. arm .. "," .. lanes)
			for layout = 1, 5 do ok(rule.floor[layout] ~= nil, "floor " .. arm .. "," .. lanes .. " layout " .. layout) end
		end
	end
	for _, arm in ipairs({ 1, 4 }) do
		eq(geom.splitterRule(spec({ splitter = 2, armType = arm })), nil, "small arms keep the shipped splitter")
	end
end)

test("patternKey: every searched axis except the radius; Arms None uses the splitter-off key", function()
	eq(geom.patternKey(spec({})), "1,2,3,1,1,1,1,1")
	eq(geom.patternKey(spec({ shape = 5, lanes = 1, radius = 9, arms = 5, splitter = 2, centre = 3, armType = 4, tram = 2, direction = 2 })),
		"5,1,5,2,3,4,2,2")
	-- Arms None builds no legs (the axis arms of a through road never get them)
	eq(geom.patternKey(spec({ shape = 5, lanes = 1, radius = 9, arms = 6, splitter = 2, centre = 3, armType = 4, tram = 2, direction = 2 })),
		"5,1,6,1,3,4,2,2")
end)

test("engine radius: exact, from the largest probed slider radius at or below the chosen one", function()
	local key = geom.patternKey(spec({}))
	with({ radius = { [key] = { [8] = 25, [20] = 0, [40] = 45 } } }, function()
		eq(geom.radiusFloor(spec({ radius = 1 })), 25)  -- 8 m
		eq(geom.radiusFloor(spec({ radius = 2 })), 25)  -- 10 m: from the 8 m cell
		eq(geom.radiusFloor(spec({ radius = 4 })), 25)  -- 15 m
		eq(geom.radiusFloor(spec({ radius = 5 })), nil) -- 20 m: 0 = the offline growth
		eq(geom.radiusFloor(spec({ radius = 6 })), nil) -- 25 m: from the 20 m cell (0)
		eq(geom.radiusFloor(spec({ radius = 9 })), 45)  -- 40 m
		eq(geom.radiusFloor(spec({ radius = 10 })), 45) -- 45 m: the cell's own radius
		eq(geom.radiusFloor(spec({ radius = 11 })), nil) -- 50 m: above it
		eq(build({ radius = 1 }).radius, 25)
		eq(build({ radius = 1 }).engine, "radius")
		eq(build({ radius = 3 }).radius, 25) -- 12 m
		eq(build({ radius = 5 }).radius, 20)
		eq(build({ radius = 5 }).engine, nil)
		eq(build({ radius = 9 }).radius, 45)
		eq(build({ radius = 1 }, { radius = 8 }).radius, 8, "the dev radius bypasses the engine radius")
		eq(build({ radius = 1, arms = 5 }).radius, 8, "other patterns unchanged")
		-- a radius between slider steps is used as is; mini follows the effective radius
		geom.setTuning({ radius = { [key] = { [8] = 13 } } })
		local b = build({ radius = 1 })
		eq(b.radius, 13)
		eq(b.mini, true)
	end)
end)

test("engine radius is exact: built even where the offline model rejects it", function()
	local over = { splitter = 2, armType = 3 } -- offline: 22 m and 25 m do not fit
	with({ radius = { [geom.patternKey(spec(over))] = { [20] = 22 } }, magic = {}, splitter = {} }, function()
		local b = build(over)
		eq(b.radius, 22)
		eq(b.engine, "radius")
		eq(b.offline, false, "the offline model rejects 22 m")
		eq(b.forced, nil, "not the forced fallback")
		eq(text(b.lists), text(build(over, { radius = 22 }).lists), "the layout the probe sent at 22 m")
	end)
	with(EMPTY, function()
		eq(build(over).radius, 30, "without engine data: the offline growth")
	end)
end)

test("splitter floor: the rule's radius per layout, exact while the slider is at most that", function()
	local rule = { split = 20, fork = 50, spread = 6, leg = 2, neck = 0, floor = { [1] = 40, [3] = 20 }, verified = { [1] = true } }
	with({ radius = {}, magic = {}, splitter = { ["2,2"] = rule } }, function()
		eq(geom.splitFloor(spec({ splitter = 2, armType = 2, arms = 3 })), 20)
		eq(geom.splitFloor(spec({ splitter = 2, armType = 2, arms = 3, radius = 4 })), 20)
		eq(geom.splitFloor(spec({ splitter = 2, armType = 2, arms = 3, radius = 6 })), nil, "25 m slider: above the floor")
		eq(geom.splitFloor(spec({ splitter = 2, armType = 2, arms = 1, radius = 6 })), 40)
		eq(geom.splitFloor(spec({ splitter = 2, armType = 2, arms = 2 })), nil, "no floor for the layout")
		eq(geom.splitFloor(spec({ splitter = 1, armType = 2, arms = 1 })), nil, "splitter off")
		eq(geom.splitFloor(spec({ splitter = 2, armType = 2, arms = 1, lanes = 1 })), nil, "no rule for 1 lane")
		local b = build({ splitter = 2, armType = 2, arms = 1, radius = 1 })
		eq(b.radius, 40)
		eq(b.engine, "splitter")
		eq(text(b.lists), text(build({ splitter = 2, armType = 2, arms = 1, radius = 1 }, { radius = 40 }).lists))
		eq(geom.splitVerified(spec({ splitter = 2, armType = 2, arms = 1 })), true)
		for _, other in ipairs({ { shape = 5 }, { centre = 2 }, { tram = 2 }, { direction = 2 }, { arms = 3 } }) do
			local o = { splitter = 2, armType = 2, arms = 1 }
			for k, v in pairs(other) do o[k] = v end
			eq(geom.splitVerified(spec(o)), false, "not what the splitter search probed")
		end
		-- an unverified floor is only a floor: the offline model must accept it, else the ring grows on
		local v = build({ splitter = 2, armType = 2, arms = 3, radius = 1 })
		eq(v.engine == nil or v.engine == "floor", true)
		ok(v.radius >= 20)
		eq(v.forced, nil)
		if v.engine == "floor" then eq(v.radius, 20); eq(v.offline, true) end
		-- the radius part (searched with the rule: search_radius_split) comes first
		local over = { splitter = 2, armType = 2, arms = 1, radius = 1 }
		geom.setTuning({ radius = { [geom.patternKey(spec(over))] = { [8] = 30 } }, magic = {}, splitter = { ["2,2"] = rule } })
		eq(build(over).radius, 30)
		eq(build(over).engine, "radius")
	end)
end)

test("magic size floor", function()
	with({ magic = { ["3,1"] = { [1] = 5, [4] = 5 }, ["2"] = { [1] = 3 } } }, function()
		local function size(over)
			local p = {}
			for k, v in pairs(over) do p[magic.PARAM_KEYS[k]] = v end
			return magic.build(magic.readParams(p)).size
		end
		eq(size({ size = 1, armType = 3, direction = 1 }), 5)
		eq(size({ size = 4, armType = 3, direction = 1 }), 5)
		eq(size({ size = 1, armType = 3, direction = 2 }), 4, "no row for clockwise: the offline growth")
		eq(size({ size = 1, armType = 2, direction = 2 }), 3, "armType-only row")
		eq(size({ size = 5, armType = 2 }), 5)
	end)
end)

test("splitter rule: replaces the defaults for its arm road; lanes-specific rows first; dev wins", function()
	local rule = { leg = 2, fork = 50, split = 30, spread = 8, neck = 10 }
	with({ radius = {}, magic = {}, splitter = { ["3"] = rule, ["3,1"] = { leg = 3 } } }, function()
		local s = spec({ splitter = 2, armType = 3 })
		eq(geom.splitterRule(s), rule)
		local sp = geom.splitParams(s)
		eq(sp.split, 30)
		near(sp.fork, math.rad(50), 1e-12)
		eq(sp.spread, 8)
		eq(sp.leg, geom.DEV_LEGS[2].entry)
		eq(sp.neck, 10)
		eq(sp.neckType, 1)
		local lanes1 = geom.splitParams(spec({ splitter = 2, armType = 3, lanes = 1 }))
		eq(lanes1.leg, geom.DEV_LEGS[3].entry)
		eq(lanes1.split, geom.SPLIT_LENGTH, "the lanes row replaces the arm row entirely")
		local dev = geom.splitParams(spec({ splitter = 2, armType = 3 }, { leg = 1, neck = 0 }))
		eq(dev.leg, geom.LEG)
		eq(dev.neck, 0)
		eq(dev.split, 30, "rule fields the dev overrides leave alone stay")
		-- other arm roads keep the shipped splitter
		local other = geom.splitParams(spec({ splitter = 2, armType = 2 }))
		eq(other.split, geom.SPLIT_LENGTH)
		eq(other.leg, geom.LEG)
		local b = build({ splitter = 2, armType = 3, radius = 9 })
		eq(roleLists(b, "legs")[1].template, geom.DEV_LEGS[2].entry.template)
		eq(#roleLists(b, "neck"), 1)
		-- forkBump still opens a rule's fork (choosePlan's nearest working layout)
		local bumped = spec({ splitter = 2, armType = 3 })
		bumped.forkBump = 2
		near(geom.splitParams(bumped).fork, math.rad(50) + 2 * geom.LEG_FORK_BUMP, 1e-12)
	end)
end)

test("shipped table: every engine radius builds exactly the layout the probe sent", function()
	local n = 0
	for pattern, cells in pairs(geom.tuning.radius) do
		local idx = {}
		for x in pattern:gmatch("[^,]+") do idx[#idx + 1] = tonumber(x) end
		local inferred = geom.tuning.inferred and geom.tuning.inferred[pattern]
		for r0, v in pairs(cells) do
			if v > 0 then
				local slider
				for i, r in ipairs(geom.RADII) do if r == r0 then slider = i end end
				local over = { shape = idx[1], lanes = idx[2], arms = idx[3], splitter = idx[4], centre = idx[5],
					armType = idx[6], tram = idx[7], direction = idx[8], radius = slider }
				-- Phase 5f: a ninth field is another through road than the arm road (its arm road index)
				if idx[9] then over.throughRoad = idx[9] + 1 end
				local b = build(over)
				if inferred then
					-- copied from anticlockwise: a floor the offline model must accept
					ok(b.radius >= v, pattern .. " from " .. r0)
					eq(b.engine == "inferred", b.radius == v, pattern .. " from " .. r0)
				else
					eq(b.radius, v, pattern .. " from " .. r0)
					eq(b.engine, "radius")
					eq(text(b.lists), text(build(over, { radius = v }).lists), pattern .. " from " .. r0)
				end
				n = n + 1
			end
		end
	end
	ok(n > 0)
end)

-- Phase 5f: radius cells of another through road than the arm road (p5_hamburger_radius)
test("through road patterns: own cells first, else the arm-road pattern's radius as a floor", function()
	local s = spec({ centre = 2, arms = 2, lanes = 1, armType = 1, radius = 1, throughRoad = 3 })
	local key, baseKey = geom.patternKey(s), geom.basePatternKey(s)
	eq(key, baseKey .. ",2")
	with({ radius = { [key] = { [8] = 25, [20] = 0 }, [baseKey] = { [8] = 20, [20] = 30 } }, magic = {}, splitter = {} }, function()
		local r, own = geom.radiusFloor(s)
		eq(r, 25); eq(own, true)
		local _, verified, source = geom.engineRadius(s)
		eq(verified, true); eq(source, "radius")
		-- 20 m: the own cell is 0 (the engine accepted the shipped radius): the arm-road pattern's floor
		local s20 = spec({ centre = 2, arms = 2, lanes = 1, armType = 1, radius = 5, throughRoad = 3 })
		r, own = geom.radiusFloor(s20)
		eq(r, 30); eq(own, false)
		_, verified, source = geom.engineRadius(s20)
		eq(verified, false); eq(source, "through")
		-- Same as arms / the arm road itself: the base pattern only
		eq(geom.radiusFloor(spec({ centre = 2, arms = 2, lanes = 1, armType = 1, radius = 1 })), 20)
		eq(geom.radiusFloor(spec({ centre = 2, arms = 2, lanes = 1, armType = 1, radius = 1, throughRoad = 2 })), 20)
	end)
	with({ radius = { [baseKey] = { [8] = 20 } }, magic = {}, splitter = {} }, function()
		local _, verified, source = geom.engineRadius(s)
		eq(verified, false); eq(source, "through", "no own cells: a floor, as before Phase 5f")
	end)
end)

-- Phase 5f: the Channelized Junction's rows (p5_channel_search)
test("channel rows: accepted angle / template, none -> ch.FALLBACK, no row -> 40 deg one-way xsmall", function()
	local ch = ug_require(DIR .. "square_roundabouts_channel.lua")
	local t = geom.tuning.channel
	ok(t and next(t) ~= nil, "channel part")
	local n = { angle = 0, none = 0 }
	for k, row in pairs(t) do
		local layout, main, side, splitter = k:match("^(%d),(%d),(%d),(%d)$")
		ok(layout, k)
		local sp = ch.readParams({ sqrb_ch_layout = tonumber(layout), sqrb_ch_main = tonumber(main), sqrb_ch_side = tonumber(side),
			sqrb_ch_splitter = tonumber(splitter) })
		local angle, slip, source = ch.slipRule(sp)
		local b = ch.build(sp)
		if row.none then
			n.none = n.none + 1
			eq(source, "fallback", k)
			ok(angle >= 50 and slip >= 2, k .. ": a steeper or wider slip lane than the rejected ones")
		else
			n.angle = n.angle + 1
			eq(source, "engine", k); eq(angle, row.angle); eq(slip, row.slip or 1)
		end
		eq(b.slipAngle, angle); eq(b.slipRoad, ch.SLIP_TEMPLATES[slip]); eq(b.slipSource, source)
	end
	print(string.format("    %d rows with an accepted angle, %d with none (fallback)", n.angle, n.none))
	-- Phase 5g: p5f_search accepted a layout for every combo nothing was accepted for before (one-way
	-- xsmall at 65 deg, else 80 deg): no `none` row, the fallback is unused with this table
	eq(n.none, 0, "none rows")
	for k, row in pairs(t) do
		eq(row.slip, nil, k .. ": one-way xsmall")
		ok(row.angle == 50 or row.angle == 65 or row.angle == 80, k .. ": " .. tostring(row.angle))
	end
	-- the default (T, town medium + town small) was accepted at 40 deg: no row
	local d = ch.build(ch.readParams({}))
	eq(d.slipAngle, 40); eq(d.slipRoad, ch.SLIP); eq(d.slipSource, nil)
	-- fallback by the most lanes per direction of a road with shared slip nodes
	with({ radius = {}, magic = {}, splitter = {}, channel = { ["2,3,1,1"] = { none = true }, ["1,1,2,1"] = { none = true } } }, function()
		eq({ ch.slipRule(ch.readParams({ sqrb_ch_layout = 2, sqrb_ch_main = 3 })) }, { 50, 3, "fallback" })
		eq({ ch.slipRule(ch.readParams({ sqrb_ch_side = 2, sqrb_ch_main = 1 })) }, { 65, 2, "fallback" })
	end)
	with(EMPTY, function()
		eq({ ch.slipRule(ch.readParams({ sqrb_ch_layout = 2, sqrb_ch_main = 3 })) }, { 40, 1 })
	end)
end)
